def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def need(x,msg):
 if not x:raise ValueError(msg)
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--build',type=Path,required=True);p.add_argument('--hosts',type=Path,nargs=14,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();b=a.build.resolve();dirs=[x.resolve() for x in a.hosts];need(len(set(dirs))==14 and not a.out.exists() and a.out.parent.is_dir(),'fresh output and 14 distinct hosts required');i=read(b/'inputs.json')
 for n,h in i['frozen'].items():need(sha(b/n)==h,'Build changed: '+n)
